ReplacementContent:
"                        {/* Sync Changes Button */}
                        {getUnsyncedItemsCount() > 0 && (
                           <button 
                              onClick={handleSyncItems}
                              className="h-9 px-4 rounded-lg text-xs font-bold uppercase tracking-wider flex items-center gap-1.5 transition-all text-white bg-emerald-600 hover:bg-emerald-700 active:scale-95 duration-100"
                           >
                              <RefreshCcw size={14} /> Sync Changes ({getUnsyncedItemsCount()})
                           </button>
                        )}

                        {/* Add Item Button */}
                        <button 
                           onClick={() => {
                              setItemMgmtForm({
                                 id: null,
                                 code: '',
                                 product_name: '',
                                 price: '',
                                 category_id: itemMgmtCategories[0]?.id || '',
                                 food_type: 'veg',
                                 description: '',
                                 current_stock: '',
                                 item_type: '0',
                                 availability: true,
                                 tax_group_id: '',
                                 department_id: '',
                                 hsn_code: '',
                                 recommended: false
                              });
                              setIsItemFormOpen(true);
                           }}
                           className="h-9 px-4 rounded-lg text-xs font-bold uppercase tracking-wider flex items-center gap-1.5 transition-all text-white bg-[#0f172a] hover:bg-[#1e293b] dark:bg-[#1e293b] dark:hover:bg-[#374151]"
                        >
                           <Plus size={14} /> Add Item
                        </button>"

